<div class="card tone-gold"><h2>Thao tác theo trình tự</h2><div class="step-actions"><button id="startTimer">1 · Tính thời gian</button><button id="practiceTimer">Thời gian thực hành</button><button id="stopTimer">2 · Kết thúc câu hỏi</button><button id="reveal">3 · Công bố đáp án</button></div><div class="row" id="roundExtras"><button id="star">★ Ngôi sao hy vọng</button><button id="puzzlePiece">Mở mảnh ghép</button><button id="finishNext">Kết thúc lượt · người tiếp</button></div></div>
<div class="card tone-gold"><h2>Đáp án và chấm điểm</h2><div id="answers"></div><div class="row"><button id="undoJudge" class="danger">Hoàn tác chấm gần nhất</button><button id="resetBuzz">Mở lại chuông</button></div><p class="muted">Tăng tốc tính điểm theo thời điểm máy chủ nhận đáp án đúng. Mỗi lần chấm được ghi vào lịch sử phiên.</p></div>
</div><div class="card tone-gold preview-card"><h2>Màn trình chiếu đang đồng bộ</h2><div id="preview"></div></div></div></section>
<section class="host-tab" data-panel="settings" hidden><div class="tab-heading"><span>04 / HỆ THỐNG</span><h2>Cài đặt nhận diện và tín hiệu</h2><p>Ảnh, video giới thiệu, logo và âm nhạc được lưu cho phiên sân khấu đang mở.</p></div><div class="card tone-rose"><h2>Thông tin kỳ thi hiện tại</h2><div class="edition-grid"><label>Tên kỳ thi<input id="editTitle"></label><label>Năm<input id="editYear" type="number" min="2020" max="2100"></label><label>Quý<select id="editQuarter"><option value="1">Quý I</option><option value="2">Quý II</option><option value="3">Quý III</option><option value="4">Quý IV</option></select></label><label>Tháng<input id="editMonth" type="number" min="1" max="12"></label></div><button id="saveEdition">Lưu thông tin kỳ thi</button></div><div class="card tone-rose"><h2>Tên bốn thí sinh</h2><div class="name-grid" id="nameInputs"></div><button id="saveNames">Lưu tên thí sinh</button></div><div class="card tone-rose"><h2>Tư liệu sân khấu</h2><div id="assets"></div><p class="muted">Ảnh PNG/JPG/WEBP tối đa 8 MB; nhạc MP3/OGG/WAV tối đa 25 MB; video MP4/WEBM tối đa 120 MB (máy chủ cần cho phép dung lượng tương ứng).</p></div></section>
<p id="message" class="notice host-message" role="status"></p></main><?php elseif($mode==='screen'): ?><button id="enableSound" style="position:absolute;z-index:9;right:12px;top:60px">Bật âm thanh trình chiếu · Toàn màn hình</button><div id="preview" style="width:min(100vw,177.77vh);margin:auto"></div><p id="message" class="notice"></p><?php elseif($mode==='mc'): ?><main class="mc-shell"><div class="card tone-cyan" id="mcJoinBox"><h2>Kết nối máy MC</h2><label>Mã phiên<input id="mcCodeInput" inputmode="numeric" maxlength="6" value="<?=htmlspecialchars($code,ENT_QUOTES)?>"></label><label>Mã MC riêng<input id="mcPin" type="password" inputmode="numeric" maxlength="6"></label><button id="mcJoin">Kết nối</button><p class="muted">Mã MC được cấp ở tab Phiên & kết nối, tách khỏi mã ghế thí sinh.</p></div><div id="mcBoard" hidden></div><p id="message" class="notice" role="status"></p></main><?php elseif($mode==='podium'): ?><main class="podium-shell"><button id="podiumFull" style="position:absolute;right:12px;top:72px;z-index:2">Toàn màn hình điểm bục</button><div id="podiumBoard"></div><p id="message" class="notice"></p></main><?php else: ?><main class="player-wrap"><div class="card" id="joinBox"><h2>Vào ghế thí sinh</h2><label>Mã phiên<input id="codeInput" inputmode="numeric" maxlength="6" value="<?=htmlspecialchars($code,ENT_QUOTES)?>"></label><label>Ghế<select id="seatJoin"><option value="0">Thí sinh 1</option><option value="1">Thí sinh 2</option><option value="2">Thí sinh 3</option><option value="3">Thí sinh 4</option></select></label><label>Mã ghế<input id="pin" type="password" inputmode="numeric" maxlength="6"></label><button id="join">Tham gia</button></div><div class="card" id="playerBox" hidden><h2 id="playerName"></h2><p id="playerPrompt"></p><p id="playerClock" class="notice"></p><button id="buzz" class="buzz">BẤM CHUÔNG</button><label>Đáp án<input id="myAnswer" autocomplete="off"></label><button id="submitAnswer">Gửi đáp án</button><p id="myStatus"></p><div id="playerScores" class="scoregrid"></div></div><p id="message" class="notice"></p></main><?php endif; ?>
<script>
const MODE=<?=json_encode($mode)?>,CSRF=<?=json_encode($csrf)?>;let code=<?=json_encode($code)?>,podiumSeat=<?=json_encode($podiumSeat)?>,state=null,rev=-1,seat=null,lastEvent=-1,serverOffset=0,waiting=false,soundEnabled=MODE!=='screen',hostFieldsLoaded=false,mcAuthorized=false,contentRound='khoi_dong',editionLoaded=false;
const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const titles={khoi_dong:'KHỞI ĐỘNG',vuot_chuong_ngai_vat:'VƯỢT CHƯỚNG NGẠI VẬT',tang_toc:'TĂNG TỐC',ve_dich:'VỀ ĐÍCH',cau_hoi_phu:'CÂU HỎI PHỤ'};
async function api(action,data={}){let form=new FormData();form.set('action',action);form.set('csrf',CSRF);form.set('code',code);Object.entries(data).forEach(([k,v])=>form.set(k,v));let r=await fetch('olympia_stage_api.php',{method:'POST',body:form,credentials:'same-origin'});let j=await r.json();if(!j.ok)throw Error(j.message||'Thao tác không thành công');return j}
function notice(e){if($('message'))$('message').textContent=e.message||String(e);else alert(e.message||String(e))}
function act(a,data){api(a,data).then(j=>{state=j.state;render()}).catch(notice)}
function portrait(i){return state?.portraits?.[i]?`<img src="${esc(state.portraits[i])}" alt="Ảnh thí sinh">`:''}
function scores(){return(state?.names||[]).map((n,i)=>`<div class="person ${state.seat===i?'active':''}">${portrait(i)}<span>${esc(n)}</span><strong>${state.scores[i]}</strong></div>`).join('')}
function remaining(){return state?.timer_end?Math.max(0,Math.ceil((state.timer_end-(Date.now()+serverOffset))/1000)):state?.timer_seconds??0}
function stageHTML(){if(!state)return '<div class="card">Chưa mở phiên.</div>';let round=state.round,scene=state.scene,h='';const media=()=>!state.media?'':state.media_type==='video'?`<video class="media" src="${esc(state.media)}" controls></video>`:state.media_type==='audio'?`<audio src="${esc(state.media)}" controls></audio>`:`<img class="media" src="${esc(state.media)}" alt="Tư liệu câu hỏi">`;const options=()=>state.options?`<div class="question-options">${esc(state.options)}</div>`:'';
 if(scene==='intro'||scene==='finished')h=`${state.intro_video&&scene==='intro'?`<video class="intro-video" src="${esc(state.intro_video)}" autoplay muted loop playsinline></video>`:''}<div class="intro-text">${scene==='finished'&&state.tie_winner!==null?'THẮNG CÂU HỎI PHỤ':scene==='finished'?'KẾT THÚC':titles[round]}</div><div>${state.tie_winner!==null&&round==='cau_hoi_phu'?esc(state.names[state.tie_winner]):'ĐƯỜNG LÊN ĐỈNH OLYMPIA · SÂN KHẤU 26'}</div><div class="scoregrid" style="width:90%">${scores()}</div>`;
 else if(scene==='pack')h=`<div class="intro-text">CHỌN GÓI CÂU HỎI</div><div class="pack-grid">${[20,20,20,30,30,30].map((n,i)=>`<span class="${state.pack[i%3]===n?'chosen':''}">${n}</span>`).join('')}</div><div>Gói ${state.pack.join(' – ')} · Tổng ${state.pack.reduce((a,b)=>a+b,0)} điểm · ${esc(state.names[state.seat])}</div>`;
 else if(scene==='puzzle'||scene==='image')h=`<div class="puzzle ${state.puzzle_open[4]?'final-open':''}" style="background:${state.puzzle_image?`url('${esc(state.puzzle_image)}') center/cover`:''}">${state.puzzle_open.slice(0,4).map((open,i)=>`<div class="${open?'open':''}">${open?'':i+1}</div>`).join('')}</div><div class="result-list" style="grid-template-columns:repeat(4,1fr);gap:4px">${state.puzzle_open.slice(0,4).map((open,i)=>`<div style="display:block">${i+1} · ${open?esc(state.puzzle_words?.[i]||'ĐÃ MỞ'):'● '.repeat((state.puzzle_words?.[i]||'OLYMPIA').length)}</div>`).join('')}</div><div>Chướng ngại vật · ${state.puzzle_open.filter(Boolean).length} mảnh đã mở ${state.puzzle_open[4]?'· GỢI Ý CUỐI':''}</div>${state.buzz?`<div class="banner">🔔 ${esc(state.names[state.buzz.seat])} TRẢ LỜI CHƯỚNG NGẠI VẬT</div>`:''}`;
 else if(scene==='star')h=`<div class="intro-text">★ NGÔI SAO HY VỌNG ★</div><div>${esc(state.names[state.seat])} · câu ${state.pack_index+1} · ${state.pack[state.pack_index]} điểm</div>`;
 else if(scene==='results'&&round==='tang_toc'){
  const rows=Object.entries(state.answers).map(([i,a])=>[+i,a]).sort((a,b)=>a[1].at-b[1].at);h=`<div class="result-list">${rows.map(([i,a])=>`<div><b>${esc(state.names[i])}</b><span>${esc(a.text)}</span><span>${((a.elapsed_ms||0)/1000).toFixed(2)}s</span><b>${a.approved?'+'+(a.awarded_points||0):'—'}</b></div>`).join('')}</div><div>Đáp án: ${esc(state.answer_key||'Đã công bố')} · Điểm theo thứ tự đúng và thời điểm trả lời</div>`;
 }else if(['khoi_dong','ve_dich'].includes(round)&&['question','results','score'].includes(scene)){
  const active=state.seat,caption=round==='khoi_dong'?(state.mode==='private'?`LƯỢT RIÊNG · ${esc(state.names[active])} · CÂU ${state.question_no}/6`:`LƯỢT CHUNG · CÂU ${state.question_no}/12 · BẤM CHUÔNG`):`${esc(state.names[active])} · CÂU ${state.pack_index+1}/3 · GÓI ${state.pack.join('–')}`;
  h=`<div class="camera-layout"><div class="camera-portrait">${state.media?media():state.portraits[active]?portrait(active):'HÌNH ẢNH THÍ SINH / SÂN KHẤU'}</div><div class="question-ribbon"><small>${caption}</small>${esc(state.question||'Đang chờ câu hỏi')}${options()}${state.revealed?`<div class="answer-line">ĐÁP ÁN: ${esc(state.answer_key||'Giám khảo công bố')}</div>`:''}</div>${round==='ve_dich'?`<div class="finish-value">${state.star_active?'★ ':''}${state.pack[state.pack_index]}</div>`:''}${state.buzz?`<div class="banner">🔔 ${esc(state.names[state.buzz.seat])} GIÀNH QUYỀN</div>`:''}</div>`;
 }else h=`<div class="prompt">${esc(state.question||'Đang chờ câu hỏi')}</div>${media()}${options()}${state.buzz?`<div class="banner">🔔 ${esc(state.names[state.buzz.seat])} GIÀNH QUYỀN</div>`:''}${state.star_active?'<div class="banner">★ NGÔI SAO HY VỌNG</div>':''}${state.question_kind==='practice'?`<div class="banner">THỰC HÀNH · ${state.practice_phase==='doing'?'ĐANG THỰC HIỆN':'SUY NGHĨ'}</div>`:''}${state.revealed?`<div class="banner">ĐÁP ÁN: ${esc(state.answer_key||'Người điều khiển công bố')}</div>`:''}<div>Câu ${state.question_no}${round==='khoi_dong'?' · '+(state.mode==='private'?'LƯỢT RIÊNG':'LƯỢT CHUNG'):''}</div>`;
 return `<div class="stage ${round==='vuot_chuong_ngai_vat'?'obstacle':round==='tang_toc'?'speed':round==='ve_dich'?'finish':round==='khoi_dong'?'start':''}"><div class="stage-head">${state.logo?`<img src="${esc(state.logo)}">`:''}⛰ ĐƯỜNG LÊN ĐỈNH OLYMPIA <span class="stage-title">${titles[round]}</span></div><div class="clock" data-clock>${remaining()}</div><div class="stage-main">${h}</div><div class="stage-scores">${scores()}</div></div>`}
function playSound(){if(!state||state.event===lastEvent)return;lastEvent=state.event;let key=state.event_name,url=state.sounds?.[key]||state.sounds?.[state.round];if(url&&soundEnabled){new Audio(url).play().catch(()=>{})}}
function render(){if(!state)return;playSound();if($('preview'))$('preview').innerHTML=stageHTML();if(MODE==='host')renderHost();if(MODE==='player')renderPlayer();if(MODE==='mc')renderMc();if(MODE==='podium')renderPodium();$('connection').textContent=`Phiên ${code} · trực tuyến`}
function renderHost(){if(!editionLoaded){const e=state.edition||{};$('editTitle').value=e.title||'';$('editYear').value=e.year||new Date().getFullYear();$('editQuarter').value=e.quarter||1;$('editMonth').value=e.month||1;editionLoaded=true}renderContent();renderControls();if(!hostFieldsLoaded){document.querySelectorAll('.nameInput').forEach((x,i)=>x.value=state.names[i]);document.querySelectorAll('.packChoice').forEach((x,i)=>x.value=state.pack[i]);hostFieldsLoaded=true;$('round').value=state.round}let box=$('answers');box.innerHTML=state.names.map((n,i)=>{let a=state.answers[i];return `<div class="row"><b>${esc(n)} (${state.scores[i]})</b><span>${a?esc(a.text)+' · '+((a.elapsed_ms||0)/1000).toFixed(2)+'s':'Chưa trả lời'}</span><button data-judge="${i}:1">Đúng</button><button class="danger" data-judge="${i}:0">Sai</button></div>`}).join('');box.querySelectorAll('[data-judge]').forEach(b=>b.onclick=()=>{let [seat,correct]=b.dataset.judge.split(':');act('judge',{seat,correct,type:state.round==='vuot_chuong_ngai_vat'&&state.buzz?'obstacle':'horizontal'})});$('star').disabled=state.star_used[state.seat]||!['pack','star'].includes(state.scene);$('star').textContent=state.star_active?'★ Đã đặt Ngôi sao':'★ Đặt Ngôi sao trước câu hỏi';$('packIndex').value=state.pack_index;document.querySelectorAll('.tieChoice').forEach(x=>x.checked=state.tie_candidates?.includes(+x.value)||false);$('finishNext').disabled=state.round!=='ve_dich'||state.scene==='finished'}
const roundHints={khoi_dong:'6 câu riêng cho từng ghế và 12 câu chung; bấm chuông ở lượt chung.',vuot_chuong_ngai_vat:'4 hàng ngang và gợi ý cuối; cấu hình ô chữ bên dưới.',tang_toc:'4 câu, thời gian 20 · 20 · 30 · 30 giây; chấm theo thời điểm nộp.',ve_dich:'3 câu mỗi người, gói 20/30 điểm; đặt Ngôi sao trước câu hỏi.',cau_hoi_phu:'Tối đa 3 câu, 15 giây; chỉ nhóm đồng điểm tham gia.'};
function bankEntries(){return Object.entries(state?.question_bank||{}).filter(([,x])=>x.round===contentRound).sort((a,b)=>a[1].seat-b[1].seat||a[1].number-b[1].number)}
function renderContent(){let nav=$('contentRounds');nav.innerHTML=Object.entries(titles).map(([key,label])=>`<button type="button" data-content="${key}" class="${key===contentRound?'active':''}">${label}</button>`).join('');$('contentHint').textContent=roundHints[contentRound];document.querySelectorAll('[data-content-round]').forEach(el=>el.hidden=el.dataset.contentRound!==contentRound);
 $('mode').closest('label').hidden=contentRound!=='khoi_dong';$('seat').closest('label').hidden=!['khoi_dong','ve_dich'].includes(contentRound);$('kind').querySelector('[value=practice]').hidden=contentRound!=='ve_dich';let max=contentRound==='khoi_dong'?($('mode').value==='common'?12:6):contentRound==='vuot_chuong_ngai_vat'?5:contentRound==='tang_toc'?4:3;$('number').max=max;if(+$('number').value>max)$('number').value=max;
 let select=$('bankSelect'),current=select.value;select.innerHTML='<option value="">Câu mới</option>'+bankEntries().map(([key,x])=>`<option value="${esc(key)}">${['khoi_dong','ve_dich'].includes(contentRound)&&x.mode!=='common'?'Ghế '+(x.seat+1)+' · ':''}Câu ${x.number} · ${esc(x.question.slice(0,65))}</option>`).join('');if(state?.question_bank?.[current]&&state.question_bank[current].round===contentRound)select.value=current;$('bankCount').textContent=`${bankEntries().length} câu đã lưu trong chặng này`}
function renderControls(){const round=state.round;$('controlStatus').textContent=`${titles[round]} · ${state.scene==='intro'?'Mở vòng':state.scene==='question'?'Đang hỏi':state.scene==='results'?'Công bố kết quả':state.scene==='finished'?'Kết thúc':state.scene} · Câu ${state.question_no}`;$('roundGuide').textContent=roundHints[round];$('roundPanel').innerHTML=`<strong>${titles[round]}</strong><p>${roundHints[round]}</p><button type="button" id="goRoundContent">Biên soạn / chọn câu ${titles[round]}</button><small>${round==='khoi_dong'?'Chọn lượt riêng hoặc lượt chung tại Nội dung.':round==='vuot_chuong_ngai_vat'?'Mở bảng ô chữ, nạp hàng ngang và mở mảnh ghép.':round==='tang_toc'?'Bốn câu, điểm chấm theo thời gian nộp đúng.':round==='ve_dich'?'Công bố gói, đặt Ngôi sao rồi mới nạp câu.':'Chọn nhóm đồng điểm, bắt đầu tính giờ trước khi bấm chuông.'}</small>`;$('goRoundContent').onclick=()=>{contentRound=round;document.querySelector('[data-tab=content]').click();renderContent()};const allowed={khoi_dong:['intro','finished'],vuot_chuong_ngai_vat:['intro','puzzle','image','finished'],tang_toc:['intro','finished'],ve_dich:['intro','pack','star','finished'],cau_hoi_phu:['intro','finished']};document.querySelectorAll('#scenes [data-scene]').forEach(b=>b.hidden=!allowed[round].includes(b.dataset.scene));$('star').hidden=round!=='ve_dich';$('finishNext').hidden=round!=='ve_dich';$('practiceTimer').hidden=round!=='ve_dich';$('puzzlePiece').hidden=round!=='vuot_chuong_ngai_vat';$('resetBuzz').hidden=!['khoi_dong','vuot_chuong_ngai_vat','ve_dich','cau_hoi_phu'].includes(round)}
function renderMc(){if(!mcAuthorized){$('mcJoinBox').hidden=false;$('mcBoard').hidden=true;return}if(!state)return;$('mcJoinBox').hidden=true;$('mcBoard').hidden=false;let buzz=state.buzz?.seat;
 $('mcBoard').innerHTML=`<div class="mc-board"><div class="mc-kicker">MÁY MC · ${esc(titles[state.round])} · CÂU ${state.question_no} · <span data-clock>${remaining()}</span> GIÂY</div><h2>${esc(state.question||'Đang chờ câu hỏi')}</h2>${state.media?(state.media_type==='audio'?`<audio src="${esc(state.media)}" controls></audio>`:state.media_type==='video'?`<video src="${esc(state.media)}" controls style="max-height:260px;max-width:100%"></video>`:`<img src="${esc(state.media)}" style="max-height:260px;max-width:100%" alt="Tư liệu câu hỏi">`):''}<div class="mc-answer">ĐÁP ÁN CHO MC: ${esc(state.answer_key||'Chưa nạp đáp án')}</div><p>${buzz!==undefined?'🔔 '+esc(state.names[buzz])+' giành quyền':'Đang chờ tín hiệu chuông'} · ${state.revealed?'Đã công bố đáp án':'Chưa công bố đáp án'}</p><div class="mc-score">${state.names.map((n,i)=>`<div>${esc(n)}<strong>${state.scores[i]}</strong></div>`).join('')}</div></div>`}
function renderPodium(){if(!state)return;const i=podiumSeat;$('podiumBoard').innerHTML=`<div class="podium-board ${state.buzz?.seat===i?'buzzing':''}"><small>ĐƯỜNG LÊN ĐỈNH OLYMPIA · BỤC ${i+1}</small>${state.portraits[i]?`<img src="${esc(state.portraits[i])}" alt="Ảnh thí sinh">`:''}<h2>${esc(state.names[i])}</h2><strong>${state.scores[i]}</strong><small>${state.buzz?.seat===i?'🔔 ĐÃ GIÀNH QUYỀN':esc(titles[state.round])}</small></div>`}
function renderPlayer(){if(seat===null)return;$('joinBox').hidden=true;$('playerBox').hidden=false;$('playerName').textContent=state.names[seat];$('playerPrompt').textContent=state.question||'Đang chờ người dẫn chương trình';$('playerScores').innerHTML=scores();$('buzz').disabled=!['question','results','puzzle','image'].includes(state.scene)||!!state.buzz||!['khoi_dong','vuot_chuong_ngai_vat','ve_dich','cau_hoi_phu'].includes(state.round)||(state.scene==='results'&&state.round!=='ve_dich')||(['puzzle','image'].includes(state.scene)&&state.round!=='vuot_chuong_ngai_vat')||(state.round==='khoi_dong'&&state.mode!=='common')||(state.round==='ve_dich'&&(state.seat===seat||!state.steal_open))||!!state.eliminated[seat];$('myStatus').textContent=state.buzz?`Chuông: ${state.names[state.buzz.seat]}`:state.my_answer?'Đã gửi: '+state.my_answer.text:''}
async function poll(){if(!code||waiting)return;waiting=true;try{let r=await fetch(`olympia_stage_api.php?action=state&code=${encodeURIComponent(code)}`,{cache:'no-store',credentials:'same-origin'}),j=await r.json();if(j.ok){serverOffset=j.server_ms-Date.now();seat=j.seat;mcAuthorized=!!j.mc;if(MODE==='mc'&&!mcAuthorized)renderMc();if(j.revision!==rev){rev=j.revision;state=j.state;render()}$('connection').textContent=`Phiên ${code} · trực tuyến`}else $('connection').textContent=j.message}catch(e){$('connection').textContent='Mất kết nối · đang thử lại'}finally{waiting=false}}
setInterval(()=>{document.querySelectorAll('[data-clock]').forEach(el=>el.textContent=remaining());if($('playerClock'))$('playerClock').textContent=state?.timer_end?'Thời gian còn: '+remaining()+' giây':''},200);setInterval(poll,500);
if(MODE==='host'){
 $('newQuarter').value=Math.ceil(+$('newMonth').value/3);$('newNames').innerHTML=[0,1,2,3].map(i=>`<label>Thí sinh ${i+1}<input class="newName" value="Thí sinh ${i+1}"></label>`).join('');
 $('create').onclick=async()=>{try{let j=await api('create',{title:$('newTitle').value,year:$('newYear').value,quarter:$('newQuarter').value,month:$('newMonth').value,names:JSON.stringify([...document.querySelectorAll('.newName')].map(x=>x.value))});code=j.code;state=null;rev=-1;hostFieldsLoaded=false;editionLoaded=false;$('codeInput').value=code;$('codes').innerHTML=`Mã phiên <b>${code}</b><br>`+j.pins.map((p,i)=>`Ghế ${i+1}: <b>${p}</b>`).join(' · ')+`<br>Mã MC: <b>${j.mc_pin}</b>`;history.replaceState(null,'',`?view=host&code=${code}`);updateLinks();poll();loadRooms()}catch(e){notice(e)}};
 $('openRoom').onclick=()=>{code=$('codeInput').value.trim();state=null;rev=-1;hostFieldsLoaded=false;editionLoaded=false;history.replaceState(null,'',`?view=host&code=${encodeURIComponent(code)}`);updateLinks();poll()};
 async function loadRooms(){try{const j=await api('rooms');$('roomsList').innerHTML=j.rooms.map(x=>`<div class="room-item"><span><b>${esc(x.edition?.title||'Olympia sân khấu')}</b> · Quý ${esc(x.edition?.quarter||'?')} / Tháng ${esc(x.edition?.month||'?')} / ${esc(x.edition?.year||'?')}<small>Mã ${esc(x.code)} · Cập nhật ${esc(x.updated_at)}</small></span><button data-open="${esc(x.code)}">Mở</button><button class="danger" data-delete="${esc(x.code)}">Xóa</button></div>`).join('')||'<p>Chưa có kỳ thi nào.</p>'}catch(e){notice(e)}}
 $('refreshRooms').onclick=loadRooms;$('roomsList').onclick=async e=>{let b=e.target.closest('button');if(!b)return;if(b.dataset.open){$('codeInput').value=b.dataset.open;$('openRoom').click()}else if(b.dataset.delete){if(!confirm('Xóa vĩnh viễn kỳ thi '+b.dataset.delete+' và toàn bộ câu hỏi, điểm, lịch sử?'))return;let old=code;code=b.dataset.delete;try{await api('delete_room');if(old===code){state=null;rev=-1;code='';$('preview').innerHTML='';$('links').innerHTML='';$('connection').textContent='Chưa mở phiên';history.replaceState(null,'','?view=host')}else code=old;loadRooms()}catch(err){code=old;notice(err)}}};loadRooms();
 $('saveEdition').onclick=()=>api('edition',{title:$('editTitle').value,year:$('editYear').value,quarter:$('editQuarter').value,month:$('editMonth').value}).then(j=>{state=j.state;render();loadRooms();notice('Đã lưu thông tin kỳ thi.')}).catch(notice);
 function updateLinks(){if(!code)return;let root=location.href.split('?')[0],q=encodeURIComponent(code);$('links').innerHTML=`<a href="${root}?view=screen&code=${q}" target="_blank"><strong>Màn hình sân khấu</strong><small>Máy chiếu chính</small></a><a href="${root}?view=mc&code=${q}" target="_blank"><strong>Máy MC</strong><small>Nhập mã MC riêng</small></a><a href="${root}?view=player&code=${q}" target="_blank"><strong>Máy thí sinh</strong><small>Mỗi người nhập mã ghế</small></a><div class="podium-links">${[0,1,2,3].map(i=>`<a href="${root}?view=podium&code=${q}&seat=${i}" target="_blank"><strong>Màn điểm bục ${i+1}</strong><small>${state?.names?.[i]||'Thí sinh '+(i+1)}</small></a>`).join('')}</div>`}updateLinks();
 document.querySelectorAll('.host-tab-button').forEach(b=>b.onclick=()=>{document.querySelectorAll('.host-tab-button').forEach(x=>{const selected=x===b;x.classList.toggle('active',selected);x.setAttribute('aria-selected',selected?'true':'false')});document.querySelectorAll('.host-tab').forEach(x=>x.hidden=x.dataset.panel!==b.dataset.tab)});
 $('rotateMc').onclick=async()=>{if(!code)return notice(Error('Hãy tạo hoặc mở phiên trước.'));if(!confirm('Cấp mã MC mới? Máy MC đã kết nối bằng mã cũ sẽ bị ngắt.'))return;try{const j=await api('rotate_mc');$('mcPinDisplay').innerHTML='Mã MC mới: <b>'+esc(j.mc_pin)+'</b>';state=j.state;render()}catch(e){notice(e)}};
 $('setRound').onclick=()=>{const target=$('round').value;if(!confirm('Mở chặng '+titles[target]+'? Thao tác này đặt lại câu và lượt đang thi.'))return;api('round',{round:target}).then(j=>{state=j.state;contentRound=target;render()}).catch(notice)};$('scenes').innerHTML=[['intro','Mở vòng'],['question','Câu hỏi'],['pack','Gói'],['star','Ngôi sao'],['puzzle','Ô chữ'],['image','Hình ảnh'],['results','Kết quả'],['score','Điểm'],['finished','Kết thúc']].map(([v,t])=>`<button data-scene="${v}">${t}</button>`).join('');$('scenes').onclick=e=>{let b=e.target.closest('[data-scene]');if(b&&!b.hidden)act('scene',{scene:b.dataset.scene})};
 $('seat').innerHTML=[0,1,2,3].map(i=>`<option value="${i}">Thí sinh ${i+1}</option>`).join('');$('nameInputs').innerHTML=[0,1,2,3].map(i=>`<label>Thí sinh ${i+1}<input class="nameInput" value="Thí sinh ${i+1}"></label>`).join('');$('saveNames').onclick=()=>api('setup',{names:JSON.stringify([...document.querySelectorAll('.nameInput')].map(x=>x.value))}).then(j=>{state=j.state;render();updateLinks()}).catch(notice);
 $('contentRounds').onclick=e=>{let b=e.target.closest('[data-content]');if(b){contentRound=b.dataset.content;$('bankSelect').value='';$('question').value='';$('answer').value='';$('options').value='';$('media').value='';$('number').value=1;renderContent()}};
 $('newMonth').onchange=()=>{$('newQuarter').value=Math.ceil(+$('newMonth').value/3)};$('editMonth').onchange=()=>{$('editQuarter').value=Math.ceil(+$('editMonth').value/3)};$('mode').onchange=renderContent;$('bankSelect').onchange=()=>{const x=state?.question_bank?.[$('bankSelect').value];if(!x){$('question').value='';$('answer').value='';$('options').value='';$('media').value='';return}$('number').value=x.number;$('seat').value=x.seat;$('mode').value=x.mode;$('kind').value=x.kind;$('question').value=x.question;$('answer').value=x.answer;$('media').value=x.media;$('mediaType').value=x.media_type||'image';$('options').value=x.options||''};
 $('loadBank').onclick=()=>{$('bankSelect').dispatchEvent(new Event('change'))};
 $('saveBank').onclick=()=>{if(!state)return notice('Hãy mở kỳ thi trước.');api('bank_save',{round:contentRound,question:$('question').value,answer:$('answer').value,media:$('media').value,media_type:$('mediaType').value,options:$('options').value,number:$('number').value,seat:$('seat').value,mode:$('mode').value,kind:$('kind').value}).then(j=>{state=j.state;render();notice('Đã lưu câu hỏi vào chặng '+titles[contentRound])}).catch(notice)};
 $('deleteBank').onclick=()=>{let key=$('bankSelect').value;if(!key)return;if(!confirm('Xóa câu hỏi đã chọn?'))return;api('bank_delete',{key}).then(j=>{state=j.state;$('bankSelect').value='';render();notice('Đã xóa câu hỏi.')}).catch(notice)};
 $('setQuestion').onclick=()=>{if(contentRound!==state?.round)return notice('Chặng biên soạn khác chặng đang điều khiển. Hãy mở đúng chặng trước.');act('question',{bank_key:$('bankSelect').value,question:$('question').value,answer:$('answer').value,media:$('media').value,media_type:$('mediaType').value,options:$('options').value,number:$('number').value,seat:$('seat').value,mode:$('mode').value,kind:$('kind').value})};$('startTimer').onclick=()=>act('timer');$('practiceTimer').onclick=()=>act('practice_timer');$('stopTimer').onclick=()=>act('stop');$('reveal').onclick=()=>act('reveal');$('undoJudge').onclick=()=>{if(confirm('Hoàn tác lần chấm gần nhất?'))act('undo_judge')};$('resetBuzz').onclick=()=>act('reset_buzz');$('star').onclick=()=>act('star');
 $('tieChoices').innerHTML=[0,1,2,3].map(i=>`<label><input type="checkbox" class="tieChoice" value="${i}">Ghế ${i+1}</label>`).join('');$('saveTie').onclick=()=>act('tie_candidates',{seats:JSON.stringify([...document.querySelectorAll('.tieChoice:checked')].map(x=>+x.value))});
 $('wordInputs').innerHTML=[0,1,2,3].map(i=>`<label>Hàng ngang ${i+1}<input class="puzzleWord"></label>`).join('');$('savePuzzle').onclick=()=>act('puzzle_config',{words:JSON.stringify([...document.querySelectorAll('.puzzleWord')].map(x=>x.value))});
 $('packChoices').innerHTML=[0,1,2].map(i=>`<label>Câu ${i+1}<select class="packChoice"><option value="20">20 điểm</option><option value="30">30 điểm</option></select></label>`).join('');$('savePack').onclick=()=>act('pack',{pack:JSON.stringify([...document.querySelectorAll('.packChoice')].map(x=>+x.value))});$('packIndex').onchange=()=>act('pack_index',{index:$('packIndex').value});$('finishNext').onclick=()=>{if(confirm('Kết thúc lượt Về đích của '+state.names[state.seat]+' và chuyển người tiếp theo?'))act('finish_next')};$('puzzlePiece').onclick=()=>{let piece=prompt('Mở mảnh ghép số mấy? (1–5)','1');if(piece&&+piece>=1&&+piece<=5)act('puzzle',{piece:+piece-1,open:1})};
 const assetGroups=[['Nhận diện & giới thiệu',[['logo','Logo chương trình','image'],['intro_video','Video giới thiệu','video'],... [0,1,2,3].map(i=>['portrait_'+i,'Ảnh thí sinh '+(i+1),'image'])]],['Hình ảnh câu hỏi',[['puzzle_image','Ảnh chướng ngại vật','image'],['media','Ảnh câu hỏi','image']]],['Âm nhạc và tín hiệu',['round','question','timer','buzz','reveal','score','star','stop'].map(x=>[x,'Tín hiệu '+x,'sound'])]];
 $('assets').innerHTML=assetGroups.map(([group,items])=>`<div class="asset-group"><h3>${group}</h3><div class="asset-grid">${items.map(([k,t,type])=>`<label>${t}<input type="file" data-key="${k}" data-kind="${type}" accept="${type==='image'?'image/png,image/jpeg,image/webp':type==='video'?'video/mp4,video/webm':'audio/mpeg,audio/ogg,audio/wav'}"></label>`).join('')}</div></div>`).join('');$('assets').onchange=async e=>{let x=e.target;if(!x.files?.[0])return;try{let form=new FormData();form.set('action','asset');form.set('csrf',CSRF);form.set('code',code);form.set('key',x.dataset.key);form.set('kind',x.dataset.kind);form.set('file',x.files[0]);let j=await(await fetch('olympia_stage_api.php',{method:'POST',body:form,credentials:'same-origin'})).json();if(!j.ok)throw Error(j.message);state=j.state;render()}catch(e){notice(e)}};
}else if(MODE==='mc'){$('mcJoin').onclick=async()=>{code=$('mcCodeInput').value.trim();state=null;rev=-1;try{await api('join_mc',{pin:$('mcPin').value});mcAuthorized=true;rev=-1;history.replaceState(null,'',`?view=mc&code=${encodeURIComponent(code)}`);poll()}catch(e){notice(e)}}}else if(MODE==='player'){$('join').onclick=async()=>{code=$('codeInput').value.trim();state=null;rev=-1;try{let j=await api('join',{seat:$('seatJoin').value,pin:$('pin').value});seat=j.seat;history.replaceState(null,'',`?view=player&code=${code}`);poll()}catch(e){notice(e)}};$('buzz').onclick=()=>act('buzz');$('submitAnswer').onclick=()=>act('submit',{answer:$('myAnswer').value})}
if(MODE==='podium')$('podiumFull').onclick=()=>document.documentElement.requestFullscreen?.().catch(()=>{});
if(MODE==='screen')$('enableSound').onclick=()=>{soundEnabled=true;$('enableSound').remove();$('preview').requestFullscreen?.().catch(()=>{});new Audio().play().catch(()=>{})};
poll();
</script></body></html>
